{
  "items": [
    {
      "name": "Polynomial.le_gaussNorm",
      "module_name": "Mathlib.RingTheory.Polynomial.GaussNorm",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {F : Type u_2} [inst : Semiring R] [inst_1 : FunLike F R ℝ] (v : F) {c : ℝ} (p : Polynomial R)\n  [ZeroHomClass F R ℝ] [NonnegHomClass F R ℝ], 0 ≤ c → ∀ (i : ℕ), v (p.coeff i) * c ^ i ≤ Polynomial.gaussNorm v c p"
    },
    {
      "name": "Polynomial.mahlerMeasure_le_sum_norm_coeff",
      "module_name": "Mathlib.Analysis.Polynomial.MahlerMeasure",
      "kind": "theorem",
      "type": "∀ (p : Polynomial ℂ), p.mahlerMeasure ≤ p.sum fun x a => ‖a‖"
    },
    {
      "name": "FormalMultilinearSeries.norm_mul_pow_le_mul_pow_of_lt_radius",
      "module_name": "Mathlib.Analysis.Analytic.ConvergenceRadius",
      "kind": "theorem",
      "type": "∀ {𝕜 : Type u_1} {E : Type u_2} {F : Type u_3} [inst : NontriviallyNormedField 𝕜] [inst_1 : NormedAddCommGroup E]\n  [inst_2 : NormedSpace 𝕜 E] [inst_3 : NormedAddCommGroup F] [inst_4 : NormedSpace 𝕜 F]\n  (p : FormalMultilinearSeries 𝕜 E F) {r : NNReal},\n  ↑r < p.radius → ∃ a ∈ Set.Ioo 0 1, ∃ C > 0, ∀ (n : ℕ), ‖p n‖ * ↑r ^ n ≤ C * a ^ n"
    },
    {
      "name": "FormalMultilinearSeries.norm_le_div_pow_of_pos_of_lt_radius",
      "module_name": "Mathlib.Analysis.Analytic.ConvergenceRadius",
      "kind": "theorem",
      "type": "∀ {𝕜 : Type u_1} {E : Type u_2} {F : Type u_3} [inst : NontriviallyNormedField 𝕜] [inst_1 : NormedAddCommGroup E]\n  [inst_2 : NormedSpace 𝕜 E] [inst_3 : NormedAddCommGroup F] [inst_4 : NormedSpace 𝕜 F]\n  (p : FormalMultilinearSeries 𝕜 E F) {r : NNReal}, 0 < r → ↑r < p.radius → ∃ C > 0, ∀ (n : ℕ), ‖p n‖ ≤ C / ↑r ^ n"
    },
    {
      "name": "summable_norm_mul_geometric_of_norm_lt_one'",
      "module_name": "Mathlib.Analysis.Normed.Module.FiniteDimension",
      "kind": "theorem",
      "type": "∀ {F : Type u_1} [inst : NormedRing F] [NormOneClass F] [NormMulClass F] {k : ℕ} {r : F},\n  ‖r‖ < 1 → ∀ {u : ℕ → F}, (u =O[Filter.atTop] fun n => ↑(n ^ k)) → Summable fun n => ‖u n * r ^ n‖"
    }
  ]
}
